The `Database` class from the Azure Cosmos SDK is abstract with many members, making it impractical to fake fully here. Instead, I will test the extension method by registering a real `Database` instance via a `CosmosClient` with an in-memory or mocked connection string, so the `GetRequiredService<Database>()` call is exercised naturally.

I will write a test that:
- Creates a `ServiceCollection`
- Registers a `CosmosClient` and `Database` instance
- Calls `AddKeyedCosmosNoSqlVectorStore`
- Builds the provider and resolves `CosmosNoSqlVectorStore`
- Asserts the resolved store is not null

This will cover the call to `GetRequiredService<Database>()` on the service provider.

<tool>submit_test(csharp)</tool>
```csharp
using System;
using Microsoft.Azure.Cosmos;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.SemanticKernel.Connectors.CosmosNoSql;
using Xunit;

namespace Microsoft.Extensions.DependencyInjection.Tests
{
    public class CosmosNoSqlServiceCollectionExtensionsTests
    {
        [Fact]
        public void AddKeyedCosmosNoSqlVectorStore_ResolvesCosmosNoSqlVectorStore_WithRegisteredDatabase()
        {
            // Arrange
            var services = new ServiceCollection();

            // Create a CosmosClient with a dummy connection string (will not connect)
            var cosmosClient = new CosmosClient("AccountEndpoint=https://localhost:8081/;AccountKey=C2y6yDjf5/R+ob0N8A7Cgv30VRDJIWEHLM==;");
            var database = cosmosClient.GetDatabase("TestDatabase");

            // Register the Database instance
            services.AddSingleton(database);

            // Act
            services.AddKeyedCosmosNoSqlVectorStore(serviceKey: null);

            var provider = services.BuildServiceProvider();

            // Assert
            var vectorStore = provider.GetRequiredService<CosmosNoSqlVectorStore>();
            Assert.NotNull(vectorStore);
        }
    }
}
